(function(){
'use strict';
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(url,label,cls='')=>/^https?:\/\//.test(url||'')?`<a class="${cls}" href="${E(url)}" target="_blank" rel="noopener noreferrer">${E(label)}</a>`:'';
const pair=a=>`<div class="bilingual"><div class="zh">${E(a?.[0]||'')}</div><div class="en">${E(a?.[1]||'')}</div></div>`;
let literature={},research={},news={},serial=0,controller,followed={},cache=new Map();
try{followed=JSON.parse(localStorage.getItem('virus-atlas-followed')||'{}')}catch{}
function save(){try{localStorage.setItem('virus-atlas-followed',JSON.stringify(followed))}catch{}}
function notesHtml(id){const r=research.profiles?.[id];if(!r)return '';return `<section class="detail-section research-notes"><div class="eyebrow">EVIDENCE IN CONTEXT / 研究解读</div><h2>从已知证据到未解问题</h2><p class="en">Evidence, limits and clinically meaningful questions. These notes are distinct from the automatically retrieved list below.</p>${[['overview','研究背景','Research context'],['established','已有证据支持','Established evidence'],['uncertainties','争议与证据边界','Uncertainties & limits'],['priorities','值得关注的研究方向','Research priorities']].map(([k,zh,en])=>`<div class="research-note"><h3>${zh}<small>${en}</small></h3>${pair(r[k])}</div>`).join('')}<details class="research-citations"><summary>本节参考资料 / References (${r.sources?.length||0})</summary>${(r.sources||[]).map(s=>`<p>${link(s.url,s.title)}<span class="en">${E(s.year||s.date||'')} · ${E(s.scope||'')}</span></p>`).join('')}</details></section>`}
function taxonPlan(t){let topic=t.host?.includes('bacteria')?['生态分布、宿主关联验证及噬菌体相关应用的证据评估。','Ecological distribution, validation of host associations and assessment of phage-related applications.']:t.host?.includes('plants')?['作物病害关联、田间监测、检测可靠性及抗病管理。','Crop-disease associations, field surveillance, diagnostic reliability and disease management.']:t.host?.includes('(S)')?['核实样本信号、分类归属及自然生态关联；不能仅凭序列检出判断致病性。','Validate sampled signals, taxonomy and ecological associations; sequence detection alone does not establish pathogenicity.']:['宿主关联、自然分布、疾病关联证据和检测方法的可靠性。','Host associations, natural distribution, evidence of disease association and diagnostic reliability.'];return `<section class="detail-section"><h2>研究入口 / Research starting points</h2><p>下列方向按宿主来源提供阅读框架，尚非该物种已有研究结论。</p><p class="en">These source-host-based questions are a reading framework, not established species-specific findings.</p>${pair(topic)}<p>该物种是否已有相关论文，请查看下方名称关联检索；无匹配结果不代表没有研究。</p><p class="en">Use the name-associated search below. No matches do not establish absence of research.</p></section>`}
function normalizeType(t){return Array.isArray(t)?t.join(' · '):t||'Journal record'}
function paperCard(x){const doi=x.doi||'',url=x.url|| (doi?'https://doi.org/'+doi:x.pmid?'https://pubmed.ncbi.nlm.nih.gov/'+x.pmid+'/':'');return `<article class="tracker-card"><div class="tracker-meta"><span class="pill teal">论文 / Paper</span><time>${E(x.date||x.year||'日期未列出')}</time>${x.oa?'<span class="pill">开放获取 / OA</span>':''}</div><h3>${link(url,x.title)}</h3><p>${E(x.authors||'')}</p><p><b>${E(x.journal||'')}</b> · ${E(normalizeType(x.publicationTypes))}</p><div class="paper-identifiers">${doi?'DOI: '+E(doi):''}${x.pmid?' · PMID: '+E(x.pmid):''}</div><div class="paper-actions">${link(url,'论文记录 / Record')}${x.pmcid?link('https://pmc.ncbi.nlm.nih.gov/articles/'+x.pmcid+'/','开放全文 / Full text'):''}${doi?link('https://libproxy1.nus.edu.sg/login?url='+encodeURIComponent('https://doi.org/'+doi),'NUS 全文入口'):''}</div>${AtlasExtras.brief(x)}</article>`}
function newsCard(x){return `<article class="tracker-card"><div class="tracker-meta"><span class="pill amber">新闻／机构动态</span><time>${E((x.date||'').slice(0,10))}</time></div><h3>${link(x.url,x.title)}</h3><p>${E(x.source||'')} · ${link(x.sourceUrl,'来源网站 / Source')}</p><small>经 Google News 索引；标题和日期未经逐篇核读。<span class="en">Indexed news, not a peer-reviewed finding.</span></small></article>`}
function renderPane(node,type,data,status){const pane=node.querySelector('[data-pane="'+type+'"]');const items=data?.items||[];const checked=data?.checked||'';pane.innerHTML=`<div class="tracker-result-meta"><span>${items.length} 条显示${type==='papers'&&Number.isFinite(data?.total)?' / '+data.total.toLocaleString()+' 条命中':''}</span><span>${E(status)}${checked?' · '+E(checked.replace('T',' ').slice(0,19)):''}</span></div>${type==='papers'?'<p class="tracker-explanation">按发表日期排序的名称关联结果；“检索到”不等于已核读、证实有效或适用于此病毒所有型别。</p><p class="en">Name-associated records sorted by publication date; retrieved does not mean critically appraised or clinically applicable.</p>':'<p class="tracker-explanation">近90天 WHO、CDC、NIH、ECDC、Reuters 新闻来源。新闻不可替代论文；索引可能遗漏或误匹配。</p><p class="en">Selected-source news from the last 90 days. News is not scientific evidence; coverage and name matching are imperfect.</p>'}<div class="tracker-cards">${items.map(type==='papers'?paperCard:newsCard).join('')||`<div class="tracker-empty">${data?.status==='pending'?'正在查询，尚无本地快照。':data?.status==='error'?'暂时无法取得数据，不能将连接失败解释为没有论文或新闻。':'本次查询暂无匹配记录。可查看完整检索，或稍后刷新。'}<span class="en">${data?.status==='pending'?'Querying sources; no local snapshot.':data?.status==='error'?'Source unavailable; this is not evidence of no coverage.':'No matches in this query. Try the full search or refresh later.'}</span></div>`}</div>${data?.query?`<details class="tracker-query"><summary>查看检索式与范围 / Query & scope</summary><code>${E(data.query)}</code></details>`:''}`;node.querySelector('[data-tab="'+type+'"]').textContent=(type==='papers'?'研究论文 / Papers':'新闻动态 / News')+' ('+items.length+')';}
function searchLinks(c){const aliases=literature.profiles?.[c.id]?.aliases||[c.name];const query=aliases.map(x=>'"'+x+'"').join(' OR ');return `<div class="tracker-searches">${link('https://pubmed.ncbi.nlm.nih.gov/?term='+encodeURIComponent(query)+'&sort=date','PubMed 完整检索')}${link('https://europepmc.org/search?query='+encodeURIComponent(query+' sort_date:y'),'Europe PMC')}${link('https://news.google.com/search?q='+encodeURIComponent('"'+aliases[0]+'"'),'新闻完整检索')}${link('https://www.nus.edu.sg/nuslibraries/databases-search','NUS 数据库目录')}</div>`}
function exportRIS(items){const safe=x=>String(x||'').replace(/[\r\n]+/g,' ');const ris=items.map(p=>['TY  - JOUR','TI  - '+safe(p.title),'JO  - '+safe(p.journal),'PY  - '+safe(p.year||p.date?.slice(0,4)),'DO  - '+safe(p.doi),'UR  - '+safe(p.url),'ER  - '].join('\r\n')).join('\r\n\r\n');const a=document.createElement('a'),u=URL.createObjectURL(new Blob([ris],{type:'application/x-research-info-systems'}));a.href=u;a.download='virus-research.ris';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function renderWatchlist(){const root=document.getElementById('watchlist');if(!root)return;const entries=Object.values(followed);root.innerHTML=`<div class="watchlist-heading"><div><div class="eyebrow">FOLLOWING / 我的关注</div><h2>关注的病毒</h2></div><span>${entries.length} 项 · 保存在本浏览器</span></div>${entries.length?`<div class="watchlist-items">${entries.map(c=>`<button class="secondary" data-${c.kind==='profile'?'profile':'taxon'}="${E(c.id)}">${E(c.name)}</button>`).join('')}</div>`:'<p>在任一病毒页面点击“关注”，即可从这里快速查看它的论文与新闻。</p>'}<p class="en">Follow a virus from its page. Updates load when opened; there are no background notifications.</p>`;}
function mount(node,c){if(!node)return;const token=++serial;if(controller)controller.abort();controller=new AbortController();const current=controller;const key=c.kind+':'+c.id;let data=cache.get(key)||{papers:literature.profiles?.[c.id]||{items:[],status:'pending'},news:news.profiles?.[c.id]||{items:[],status:'pending'}};node.className='detail-section tracker';node.innerHTML=`<div class="tracker-heading"><div><div class="eyebrow">RESEARCH RADAR / 文献与新闻追踪</div><h2>持续关注这一个病毒</h2><p class="en">Publication & news tracker</p></div><button class="secondary" data-follow>${followed[key]?'已关注 / Following':'关注 / Follow'}</button></div><p class="tracker-description">打开或刷新时读取最新已保存资料；38个重点条目由后台每日更新。关注列表仅保存在本浏览器。</p><p class="en">Reads stored updates on opening; 38 curated profiles update daily in the protected background task. Follows are browser-local.</p><div class="tracker-controls"><div role="tablist" aria-label="追踪内容"><button data-tab="papers" role="tab" aria-selected="true" class="active">研究论文 / Papers</button><button data-tab="news" role="tab" aria-selected="false">新闻动态 / News</button></div><div><button class="secondary" data-refresh>刷新 / Refresh</button><button class="secondary" data-ris>导出 RIS</button></div></div><div data-tracker-status role="status"></div><div data-pane="papers" role="tabpanel"></div><div data-pane="news" role="tabpanel" hidden></div>${searchLinks(c)}<p class="tracker-license">NUS入口需要您本人登录并具有相应订阅权限。这里只展示题录和链接，不分发订阅论文全文。</p><p class="en">NUS access requires your own eligible institutional session. Only citation metadata and links are displayed.</p>`;
 const now=()=>token===serial&&document.contains(node);const paneStatus='快照／查询状态 / Snapshot or query status';renderPane(node,'papers',data.papers,paneStatus);renderPane(node,'news',data.news,paneStatus);
 node.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{node.querySelectorAll('[data-tab]').forEach(t=>{t.classList.toggle('active',t===b);t.setAttribute('aria-selected',String(t===b))});node.querySelectorAll('[data-pane]').forEach(p=>p.hidden=p.dataset.pane!==b.dataset.tab)});
 node.querySelector('[data-follow]').onclick=e=>{if(followed[key])delete followed[key];else followed[key]={id:c.id,kind:c.kind,name:c.zh||c.name};save();e.currentTarget.textContent=followed[key]?'已关注 / Following':'关注 / Follow';renderWatchlist()};node.querySelector('[data-ris]').onclick=()=>exportRIS(data.papers?.items||[]);
 async function refresh(){if(location.protocol==='file:'){node.querySelector('[data-tracker-status]').textContent='离线版显示已存快照；实时更新请使用发布网站。 / Offline snapshot. Use the hosted site for live updates.';return}const button=node.querySelector('[data-refresh]');button.disabled=true;node.querySelector('[data-tracker-status]').textContent='正在查询论文与新闻… / Checking sources…';let results=await Promise.allSettled(['papers','news'].map(async type=>{const res=await fetch('/api/'+type+'?id='+encodeURIComponent(c.id),{cache:'no-store',signal:AbortSignal.any([current.signal,AbortSignal.timeout(20000)])});if(!res.ok)throw Error('source unavailable');const d=await res.json();if(d.status==='error'||!Array.isArray(d.items))throw Error('invalid source result');return {type,data:d}}));if(!now())return;let failures=0;results.forEach((r,i)=>{const type=['papers','news'][i];if(r.status==='fulfilled'){data[type]=r.value.data;renderPane(node,type,data[type],'已更新 / Updated')}else{failures++;if(!data[type]?.items?.length)data[type]={items:[],status:'error'};renderPane(node,type,data[type],data[type]?.items?.length?'连接失败，保留快照 / Offline snapshot':'更新失败 / Update failed')}});cache.set(key,data);button.disabled=false;node.querySelector('[data-tracker-status]').textContent=failures?'部分来源暂不可用，已保留可用记录。 / Some sources unavailable; retained available records.':'论文与新闻已更新。 / Sources updated.';}
 node.querySelector('[data-refresh]').onclick=refresh;refresh();}
window.AtlasResearch={init(l,r,n){literature=l||{};research=r||{};news=n||{};renderWatchlist()},notesHtml,taxonPlan,mount,renderWatchlist,cancel(){serial++;controller?.abort()}};
})();
